// Title: C# – Hide Rows Generated by Aspose.Cells Smart Markers After Applying an AutoFilter
// Description: Demonstrates how to use WorkbookDesigner to expand smart markers, apply an AutoFilter on a column, and call AutoFilter.Refresh(true) so rows that don't meet the filter (e.g., non‑USA records) are automatically hidden before saving the workbook.
// Keywords: Aspose.Cells | C# | Smart Markers | WorkbookDesigner | AutoFilter | hide filtered rows | Excel report generation | AutoFilter.Refresh | smart marker rows hide | filter rows hide
// Common Searches: hide rows created by smart markers Aspose.Cells | auto hide filtered rows after WorkbookDesigner processing | Aspose.Cells C# hide rows that don't match AutoFilter | smart markers filter rows hide example | how to hide non‑matching rows in generated Excel with Aspose
// Developer Intent: Automatically hide rows added by smart markers that are excluded by an AutoFilter.
// Use Cases: Generate a dynamic Excel report with smart markers and display only rows for a selected country, hiding all others. | Create a clean worksheet where rows inserted by WorkbookDesigner are concealed when they fail a filter condition. | Produce a final file that contains no visible empty or irrelevant rows after applying data‑driven filters.
// AI Prompts: Provide C# code that expands Aspose.Cells smart markers with WorkbookDesigner and hides rows not matching an AutoFilter using Refresh(true). | Explain how to configure Aspose.Cells AutoFilter to automatically conceal rows generated by smart markers after filtering. | Show a step‑by‑step example of applying an AutoFilter on a smart‑marker‑filled column and ensuring non‑matching rows are hidden in the saved workbook.

using System;
using System.Collections.Generic;
using Aspose.Cells;

namespace AsposeCellsSmartMarkerFilterDemo
{
    // Sample data class for smart markers
    // Demonstrates how to use WorkbookDesigner to expand smart markers, apply an AutoFilter on a column, and call AutoFilter.Refresh(true) so rows that don't meet the filter (e.g., non‑USA records) are automatically hidden before saving the workbook.
    public class Person
    {
        public string Name { get; set; }
        public int Age { get; set; }
        public string Country { get; set; }
    }

    public class Program
    {
        public static void Main()
        {
            // 1. Create a new workbook (template)
            Workbook workbook = new Workbook();
            Worksheet sheet = workbook.Worksheets[0];

            // 2. Set up smart markers in the worksheet.
            // Header row
            sheet.Cells["A1"].PutValue("Name");
            sheet.Cells["B1"].PutValue("Age");
            sheet.Cells["C1"].PutValue("Country");

            // Smart marker rows (will be expanded by the designer)
            sheet.Cells["A2"].PutValue("&=Persons.Name");
            sheet.Cells["B2"].PutValue("&=Persons.Age");
            sheet.Cells["C2"].PutValue("&=Persons.Country");

            // 3. Prepare data source
            List<Person> persons = new List<Person>
            {
                new Person { Name = "John", Age = 28, Country = "USA" },
                new Person { Name = "Anna", Age = 34, Country = "UK" },
                new Person { Name = "Li", Age = 22, Country = "China" },
                new Person { Name = "Maria", Age = 45, Country = "USA" }
            };

            // 4. Process smart markers
            WorkbookDesigner designer = new WorkbookDesigner
            {
                Workbook = workbook,
                // Use range smart markers (LineByLine is obsolete, but kept for completeness)
                LineByLine = false
            };
            designer.SetDataSource("Persons", persons);
            designer.Process();

            // 5. Apply an AutoFilter on the "Country" column (C) to show only USA rows
            sheet.AutoFilter.Range = "A1:C" + sheet.Cells.MaxDataRow; // include all populated rows
            sheet.AutoFilter.AddFilter(2, "USA"); // column index 2 = C (Country)

            // 6. Refresh the filter and hide the rows that do not meet the criteria
            // hideRows = true ensures filtered-out rows become hidden
            sheet.AutoFilter.Refresh(true);

            // 7. Save the result
            workbook.Save("SmartMarkerFiltered.xlsx", SaveFormat.Xlsx);
        }
    }
}
